import{_ as t,o as s,c as a,a3 as i}from"./chunks/framework.BHpftTUY.js";const u=JSON.parse('{"title":"General configuration","description":"The general section defines infrastructure settings shared across all listeners. Individual services can override ssl per-listener with their own ssl…","frontmatter":{"outline":[2,4],"head":[["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/installation/general.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/2.4.5/installation/general.html"}],["meta",{"property":"og:title","content":"General configuration"}],["meta",{"name":"twitter:title","content":"General configuration"}],["meta",{"property":"og:description","content":"The general section defines infrastructure settings shared across all listeners. Individual services can override ssl per-listener with their own ssl…"}],["meta",{"name":"twitter:description","content":"The general section defines infrastructure settings shared across all listeners. Individual services can override ssl per-listener with their own ssl…"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/2.4.5/installation/general.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/2.4.5/installation/general.html\\",\\"headline\\":\\"General configuration\\",\\"description\\":\\"The general section defines infrastructure settings shared across all listeners. Individual services can override ssl per-listener with their own ssl…\\",\\"dateModified\\":\\"2026-10-31T12:43:41.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/2.4.5/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"General configuration\\",\\"item\\":\\"https://doc.yarilomail.org/2.4.5/installation/general.html\\"}]}]}"]]},"headers":[],"relativePath":"installation/general.md","filePath":"installation/general.md","lastUpdated":1793450621000}'),r={name:"installation/general.md"};function d(n,e,l,o,c,h){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="general-configuration" tabindex="-1">General configuration <a class="header-anchor" href="#general-configuration" aria-label="Permalink to &quot;General configuration&quot;">​</a></h1><p>The <code>general</code> section defines infrastructure settings shared across all listeners. Individual services can override <code>ssl</code> per-listener with their own <code>ssl:</code> block.</p><h2 id="how-numeric-settings-read" tabindex="-1">How numeric settings read <a class="header-anchor" href="#how-numeric-settings-read" aria-label="Permalink to &quot;How numeric settings read&quot;">​</a></h2><p>The defaults in these pages are the binary&#39;s, and the Helm chart&#39;s <code>values.<wbr>yaml</code> carries the same numbers. From 2.4.2:</p><ul><li>A key left out keeps its default, in <code>yarilo.<wbr>yaml</code> and in each entry of a list (<code>oauth2</code>, <code>quota_<wbr>warnings</code>, <code>mail_<wbr>servers</code>).</li><li>An explicit <code>0</code> turns a setting off (a cache, a delay, a limit, an interval that may stop), as each table says. Where off makes no sense (a timeout that must bound, a pool size, a poll interval), an explicit <code>0</code> stops the process at startup with the key&#39;s name.</li><li>A negative value is refused, except where a page says otherwise (<code>lmtp_<wbr>user_<wbr>concurrency_<wbr>limit: -1</code> is unlimited).</li></ul><hr><h2 id="hostname-top-level" tabindex="-1"><code>hostname</code> (top level) <a class="header-anchor" href="#hostname-top-level" aria-label="Permalink to &quot;`hostname` (top level)&quot;">​</a></h2><p>What this installation calls itself.</p><h3 id="hostname" tabindex="-1"><code>hostname</code> <a class="header-anchor" href="#hostname" aria-label="Permalink to &quot;`hostname` {#hostname}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>the host&#39;s own name (<code>os.Hostname()</code>)</dd><dt>Type</dt><dd>string</dd></dl></div><p>The name yarilo answers with and stamps into mail. It sits at the top level of <code>yarilo.<wbr>yaml</code>, not inside <code>general:</code>, because more than one section reads it.</p><p>Four things read it:</p><ul><li>the domain part of a <code>Message-ID</code> synthesised at delivery (see <a href="/2.4.5/protocols/lmtp.html">LMTP</a>),</li><li>the LMTP <code>LHLO</code> banner,</li><li>the <code>Received:</code> header added at delivery,</li><li>submission&#39;s banner and <code>Message-ID</code> domain - unless <code>protocol.<wbr>submission.<wbr>hostname</code> is set, which overrides <strong>submission alone</strong>.</li></ul><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">hostname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mail.example.com</span></span></code></pre></div><p><strong>Set it on a cluster.</strong> The default is each process&#39;s own hostname, which is right for a single node and wrong for several: every pod would answer with a different name, and the identifiers they write would disagree about where the mail came from. The correct value is the name your mail is seen under, and it is a decision that cannot be defaulted into.</p><p>Leaving it explicitly empty is possible and produces a placeholder name in those headers. That is deliberate: a missing setting should be visible in the mail rather than silently plausible.</p><hr><h2 id="chart-version-top-level-chart-managed" tabindex="-1"><code>chart_<wbr>version</code> (top level, chart-managed) <a class="header-anchor" href="#chart-version-top-level-chart-managed" aria-label="Permalink to &quot;`chart_version` (top level, chart-managed)&quot;">​</a></h2><p>Written by the Helm chart, not by an operator. It carries the chart&#39;s own version so a process can say whether the ConfigMap beside it was rendered by the same release it was built from - <code>helm upgrade --set image.<wbr>tag=X</code> pairs a binary with whatever chart is on disk, and a chart older than the binary silently fails to render keys the binary reads.</p><h3 id="chart_version" tabindex="-1"><code>chart_<wbr>version</code> <a class="header-anchor" href="#chart_version" aria-label="Permalink to &quot;`chart_version` {#chart_version}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd></dl><p class="setting-advanced">Advanced: this should not normally be changed.</p></div><p>Written by the Helm chart, never by an operator. A process compares it with the chart version it was built from and warns at start when they differ.</p><p><strong>Do not set it.</strong> There is no such value in <code>values.<wbr>yaml</code>, so a Helm deployment cannot reach it. A hand-written <code>yarilo.<wbr>yaml</code> that carries a different value gets a warning at start and nothing else: refusing to start over a version string would be a worse failure than the one being reported.</p><hr><h2 id="general-ssl" tabindex="-1"><code>general.<wbr>ssl</code> <a class="header-anchor" href="#general-ssl" aria-label="Permalink to &quot;`general.ssl`&quot;">​</a></h2><p>Shared TLS certificate. Used by every TLS-enabled listener that does not define its own <code>ssl:</code> override.</p><h3 id="general.ssl.ssl_server_cert_file" tabindex="-1"><code>ssl_<wbr>server_<wbr>cert_<wbr>file</code> <a class="header-anchor" href="#general.ssl.ssl_server_cert_file" aria-label="Permalink to &quot;`ssl_server_cert_file` {#general.ssl.ssl_server_cert_file}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Also accepted as</dt><dd><code>tls_cert</code></dd><dt>See also</dt><dd><a href="/2.4.5/installation/general.html#general.ssl.ssl_server_key_file"><code>ssl_server_key_file</code></a></dd></dl></div><p>Path to the PEM certificate, or the full chain. <code>${ENV_<wbr>VAR}</code> is expanded at startup.</p><h3 id="general.ssl.ssl_server_key_file" tabindex="-1"><code>ssl_<wbr>server_<wbr>key_<wbr>file</code> <a class="header-anchor" href="#general.ssl.ssl_server_key_file" aria-label="Permalink to &quot;`ssl_server_key_file` {#general.ssl.ssl_server_key_file}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Also accepted as</dt><dd><code>tls_key</code></dd><dt>See also</dt><dd><a href="/2.4.5/installation/general.html#general.ssl.ssl_server_cert_file"><code>ssl_server_cert_file</code></a></dd></dl></div><p>Path to the PEM private key that matches <code>ssl_<wbr>server_<wbr>cert_<wbr>file</code>.</p><h3 id="general.ssl.ssl_server_alt_cert_file" tabindex="-1"><code>ssl_<wbr>server_<wbr>alt_<wbr>cert_<wbr>file</code> <a class="header-anchor" href="#general.ssl.ssl_server_alt_cert_file" aria-label="Permalink to &quot;`ssl_server_alt_cert_file` {#general.ssl.ssl_server_alt_cert_file}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Also accepted as</dt><dd><code>tls_alt_cert</code></dd><dt>See also</dt><dd><a href="/2.4.5/installation/general.html#general.ssl.ssl_server_alt_key_file"><code>ssl_server_alt_key_file</code></a></dd></dl></div><p>Optional second certificate, for example ECDSA beside RSA, chosen per client by SNI.</p><h3 id="general.ssl.ssl_server_alt_key_file" tabindex="-1"><code>ssl_<wbr>server_<wbr>alt_<wbr>key_<wbr>file</code> <a class="header-anchor" href="#general.ssl.ssl_server_alt_key_file" aria-label="Permalink to &quot;`ssl_server_alt_key_file` {#general.ssl.ssl_server_alt_key_file}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Also accepted as</dt><dd><code>tls_alt_key</code></dd><dt>See also</dt><dd><a href="/2.4.5/installation/general.html#general.ssl.ssl_server_alt_cert_file"><code>ssl_server_alt_cert_file</code></a></dd></dl></div><p>Private key for <code>ssl_<wbr>server_<wbr>alt_<wbr>cert_<wbr>file</code>.</p><h3 id="general.ssl.ssl_min_protocol" tabindex="-1"><code>ssl_<wbr>min_<wbr>protocol</code> <a class="header-anchor" href="#general.ssl.ssl_min_protocol" aria-label="Permalink to &quot;`ssl_min_protocol` {#general.ssl.ssl_min_protocol}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>TLS1.2</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>TLS1.2</code> <code>TLS1.3</code></dd><dt>Also accepted as</dt><dd><code>tls_min_version</code></dd></dl></div><p>Minimum TLS version a client may negotiate.</p><h3 id="general.ssl.ssl_prefer_server_ciphers" tabindex="-1"><code>ssl_<wbr>prefer_<wbr>server_<wbr>ciphers</code> <a class="header-anchor" href="#general.ssl.ssl_prefer_server_ciphers" aria-label="Permalink to &quot;`ssl_prefer_server_ciphers` {#general.ssl.ssl_prefer_server_ciphers}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Also accepted as</dt><dd><code>prefer_server_ciphers</code></dd></dl></div><p>Use the server&#39;s cipher-suite preference order instead of the client&#39;s.</p><p><strong>TLS ALPN matching (the reference parity).</strong> TLS listeners advertise ALPN protocol identifiers per IANA RFC 7301: <code>imap</code> for IMAP/IMAPS, <code>pop3</code> for POP3/POP3S, <code>smtp</code> for Submission/Submissions. Clients that send ALPN must match - mismatching connections are refused. Clients without ALPN are accepted (backward-compatibility). LMTP is internal-only and does not enforce ALPN.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">general</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ssl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ssl_server_cert_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/ssl/yarilo/cert.pem</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ssl_server_key_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/ssl/yarilo/key.pem</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ssl_server_alt_cert_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/ssl/yarilo/ecdsa.pem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # optional</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ssl_server_alt_key_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/ssl/yarilo/ecdsa.key</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ssl_min_protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TLS1.2</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ssl_prefer_server_ciphers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p><code>${ENV_<wbr>VAR}</code> substitution is supported in all path values - no secrets in config files.</p><hr><h2 id="general-haproxy" tabindex="-1"><code>general.<wbr>haproxy</code> <a class="header-anchor" href="#general-haproxy" aria-label="Permalink to &quot;`general.haproxy`&quot;">​</a></h2><p>HAProxy PROXY protocol v1/v2. When <code>haproxy_<wbr>protocol: true</code> is set on a service, the real client IP is extracted from the <code>PROXY</code> header. Connections from addresses outside <code>haproxy_<wbr>trusted_<wbr>networks</code> ignore the header (the TCP source IP is used instead).</p><h3 id="general.haproxy.timeout" tabindex="-1"><code>timeout</code> <a class="header-anchor" href="#general.haproxy.timeout" aria-label="Permalink to &quot;`timeout` {#general.haproxy.timeout}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>3</code></dd><dt>Type</dt><dd>integer, seconds</dd></dl></div><p>Time to wait for the PROXY header. The connection is closed when it does not arrive in time.</p><h3 id="general.haproxy.haproxy_trusted_networks" tabindex="-1"><code>haproxy_<wbr>trusted_<wbr>networks</code> <a class="header-anchor" href="#general.haproxy.haproxy_trusted_networks" aria-label="Permalink to &quot;`haproxy_trusted_networks` {#general.haproxy.haproxy_trusted_networks}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>127.0.0.1/32, 10.0.0.0/8</code></dd><dt>Type</dt><dd>list</dd><dt>Also accepted as</dt><dd><code>trusted_nets</code></dd></dl></div><p>CIDRs whose PROXY headers are accepted. A connection from anywhere else keeps its TCP source address.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">general</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  haproxy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    haproxy_trusted_networks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">127.0.0.1/32</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">10.0.0.0/8</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">172.16.0.0/12</span></span></code></pre></div><p>Enable per-listener with <code>haproxy_<wbr>protocol: true</code> in the service config. See <a href="/2.4.5/architecture/services.html">Services configuration</a>.</p><hr><h2 id="general-xclient" tabindex="-1"><code>general.<wbr>xclient</code> <a class="header-anchor" href="#general-xclient" aria-label="Permalink to &quot;`general.xclient`&quot;">​</a></h2><p>SMTP XCLIENT command for trusted relay infrastructure. A relay behind which yarilo sits can pass the real client IP, hostname, and helo string via XCLIENT before the mail transaction begins.</p><p>Only a peer inside <code>trusted_<wbr>nets</code> is believed. The same list decides who is told about XCLIENT at all: submission-login and lmtp-login list <code>XCLIENT</code> in their EHLO/LHLO reply only to such a peer. A peer outside it that sends XCLIENT anyway gets the same reply as a trusted one, and its address is not applied, so the reply does not reveal who is trusted.</p><p><strong>Supported XCLIENT attributes:</strong> <code>ADDR</code>, <code>PORT</code>, <code>HELO</code>, <code>LOGIN</code>, <code>PROTO</code>, <code>SESSION</code>, <code>TTL</code>, <code>FORWARD</code>, plus the reference extensions <code>DESTADDR</code> (alias: <code>DESTIP</code>) and <code>DESTPORT</code> for the destination the client originally connected to (load-balancer awareness).</p><h3 id="general.xclient.trusted_nets" tabindex="-1"><code>trusted_<wbr>nets</code> <a class="header-anchor" href="#general.xclient.trusted_nets" aria-label="Permalink to &quot;`trusted_nets` {#general.xclient.trusted_nets}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>[]</code></dd><dt>Type</dt><dd>list</dd><dt>Changed 2.4.4</dt><dd>The default was <code>127.0.0.1/32, 10.0.0.0/8</code>; it now trusts nobody.</dd></dl></div><p>CIDRs of the proxies and relays allowed to issue XCLIENT. Empty trusts none.</p><p>Name your proxies&#39; networks:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">general</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  xclient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    trusted_nets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">10.0.0.0/8</span></span></code></pre></div><p>Enable per-listener with <code>xclient_<wbr>protocol: true</code> in the service config. See <a href="/2.4.5/architecture/services.html">Services configuration</a>. A listener with <code>xclient_<wbr>protocol: true</code> while <code>trusted_<wbr>nets</code> is empty logs a warning at start: no forwarded address will be believed. The same applies to the JMAP backend&#39;s trust mode 2, which reads this list.</p><div class="warning custom-block"><p class="custom-block-title">Upgrading</p><p>An installation that relied on the earlier default <code>127.<wbr>0.<wbr>0.<wbr>1/<wbr>32, 10.<wbr>0.<wbr>0.<wbr>0/<wbr>8</code> without writing it out now trusts nobody. A chart-rendered config writes the list explicitly, so it keeps what its values say.</p></div><hr><h2 id="general-limits" tabindex="-1"><code>general.<wbr>limits</code> <a class="header-anchor" href="#general-limits" aria-label="Permalink to &quot;`general.limits`&quot;">​</a></h2><h3 id="general.limits.mail_max_userip_connections" tabindex="-1"><code>mail_<wbr>max_<wbr>userip_<wbr>connections</code> <a class="header-anchor" href="#general.limits.mail_max_userip_connections" aria-label="Permalink to &quot;`mail_max_userip_connections` {#general.limits.mail_max_userip_connections}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>10</code></dd><dt>Type</dt><dd>integer</dd></dl></div><p>Simultaneous connections per user and IP pair, counted across all IMAP and POP3 listeners. <code>0</code> is unlimited. A userdb field of the same name overrides it per user.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">general</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  limits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    mail_max_userip_connections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span></code></pre></div><hr><h2 id="general-startup-dial-retries" tabindex="-1"><code>general.<wbr>startup_<wbr>dial_<wbr>retries</code> <a class="header-anchor" href="#general-startup-dial-retries" aria-label="Permalink to &quot;`general.startup_dial_retries`&quot;">​</a></h2><h3 id="general.startup_dial_retries" tabindex="-1"><code>startup_<wbr>dial_<wbr>retries</code> <a class="header-anchor" href="#general.startup_dial_retries" aria-label="Permalink to &quot;`startup_dial_retries` {#general.startup_dial_retries}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>3</code></dd><dt>Type</dt><dd>integer</dd></dl></div><p>Attempts to reach an external dependency, such as warden or Redis, at startup before the process gives up.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">general</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  startup_dial_retries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span></code></pre></div><h2 id="login-login-proxy-timeout" tabindex="-1"><code>login.<wbr>login_<wbr>proxy_<wbr>timeout</code> <a class="header-anchor" href="#login-login-proxy-timeout" aria-label="Permalink to &quot;`login.login_proxy_timeout`&quot;">​</a></h2><p>Read by the IMAP, POP3, Submission and ManageSieve login proxies.</p><h3 id="login.login_proxy_timeout" tabindex="-1"><code>login_<wbr>proxy_<wbr>timeout</code> <a class="header-anchor" href="#login.login_proxy_timeout" aria-label="Permalink to &quot;`login_proxy_timeout` {#login.login_proxy_timeout}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>30</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>login.login_proxy_timeout</code></dd></dl></div><p>Time a login proxy may spend reaching the user&#39;s backend and bringing the session up there: the connect, re-routes to another backend, the preamble and the backend&#39;s greeting, with every retry inside the same window. Past it the client gets a temporary failure (<code>NO [UNAVAILABLE]</code> on IMAP) and may log in again. A user&#39;s <code>proxy_<wbr>timeout</code> (see <a href="/2.4.5/auth/">Authentication</a>) replaces it.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">login</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  login_proxy_timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span></span></code></pre></div><h2 id="login-transient-retries" tabindex="-1"><code>login</code> transient retries <a class="header-anchor" href="#login-transient-retries" aria-label="Permalink to &quot;`login` transient retries&quot;">​</a></h2><p>Read by the IMAP, POP3, Submission and ManageSieve login proxies.</p><h3 id="login.transient_retries" tabindex="-1"><code>transient_<wbr>retries</code> <a class="header-anchor" href="#login.transient_retries" aria-label="Permalink to &quot;`transient_retries` {#login.transient_retries}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>3</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>login.transientRetries</code></dd><dt>See also</dt><dd><a href="/2.4.5/installation/general.html#login.transient_relogin_cap"><code>transient_relogin_cap</code></a></dd></dl></div><p>Extra attempts a transient failure gets (auth temporary failure, auth dial, backend session setup) before the client is told the service is unavailable. <code>0</code> fails on the first error.</p><h3 id="login.transient_relogin_cap" tabindex="-1"><code>transient_<wbr>relogin_<wbr>cap</code> <a class="header-anchor" href="#login.transient_relogin_cap" aria-label="Permalink to &quot;`transient_relogin_cap` {#login.transient_relogin_cap}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>3</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>login.transientReloginCap</code></dd><dt>See also</dt><dd><a href="/2.4.5/installation/general.html#login.transient_retries"><code>transient_retries</code></a></dd></dl></div><p>Once the retries are spent, the proxy answers <code>NO [UNAVAILABLE]</code> and keeps the connection open for another login. This many such answers close the connection. Independent of <code>auth_<wbr>max_<wbr>attempts</code>. <code>0</code> closes on the first.</p><h2 id="startup-waits" tabindex="-1">Startup waits <a class="header-anchor" href="#startup-waits" aria-label="Permalink to &quot;Startup waits&quot;">​</a></h2><p>A process that starts while a dependency rolls waits for it instead of exiting into a restart loop. The wait applies at startup only; requests do not use it.</p><h3 id="auth_service.auth_startup_wait" tabindex="-1"><code>auth_<wbr>startup_<wbr>wait</code> <a class="header-anchor" href="#auth_service.auth_startup_wait" aria-label="Permalink to &quot;`auth_startup_wait` {#auth_service.auth_startup_wait}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>30</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.auth.startup_wait</code></dd></dl></div><p>Time to wait for yarilo-auth at startup. <code>0</code> does not wait.</p><h3 id="locks_client.locks_client_startup_wait" tabindex="-1"><code>locks_<wbr>client_<wbr>startup_<wbr>wait</code> <a class="header-anchor" href="#locks_client.locks_client_startup_wait" aria-label="Permalink to &quot;`locks_client_startup_wait` {#locks_client.locks_client_startup_wait}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>30</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.locks.client.startup_wait</code></dd></dl></div><p>Time to wait for yarilo-locks at startup. <code>0</code> does not wait.</p><h2 id="auth-client-pool" tabindex="-1"><code>auth_<wbr>client</code> pool <a class="header-anchor" href="#auth-client-pool" aria-label="Permalink to &quot;`auth_client` pool&quot;">​</a></h2><p>Userdb lookups from session processes reuse pooled connections to yarilo-auth.</p><h3 id="auth_client.auth_client_pool_size" tabindex="-1"><code>auth_<wbr>client_<wbr>pool_<wbr>size</code> <a class="header-anchor" href="#auth_client.auth_client_pool_size" aria-label="Permalink to &quot;`auth_client_pool_size` {#auth_client.auth_client_pool_size}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>4</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>components.auth.client.pool_size</code></dd></dl></div><p>Connections to yarilo-auth kept open for userdb lookups. <code>0</code> dials per lookup. On shutdown each connection still serving a lookup is waited for up to a second.</p><h3 id="auth_client.auth_client_pool_idle_timeout" tabindex="-1"><code>auth_<wbr>client_<wbr>pool_<wbr>idle_<wbr>timeout</code> <a class="header-anchor" href="#auth_client.auth_client_pool_idle_timeout" aria-label="Permalink to &quot;`auth_client_pool_idle_timeout` {#auth_client.auth_client_pool_idle_timeout}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>300</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>components.auth.client.pool_idle_timeout</code></dd></dl></div><p>Time an unused pooled connection is kept. <code>0</code> never closes one for idleness.</p><h2 id="internal-tls-session-resumption" tabindex="-1"><code>internal_<wbr>tls</code> session resumption <a class="header-anchor" href="#internal-tls-session-resumption" aria-label="Permalink to &quot;`internal_tls` session resumption&quot;">​</a></h2><h3 id="internal_tls.session_cache_size" tabindex="-1"><code>session_<wbr>cache_<wbr>size</code> <a class="header-anchor" href="#internal_tls.session_cache_size" aria-label="Permalink to &quot;`session_cache_size` {#internal_tls.session_cache_size}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>64</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>internalTLS.sessionCacheSize</code></dd></dl></div><p>TLS sessions an internal client keeps for resumption. <code>0</code> turns resumption off.</p><h3 id="internal_tls.session_cache_ttl" tabindex="-1"><code>session_<wbr>cache_<wbr>ttl</code> <a class="header-anchor" href="#internal_tls.session_cache_ttl" aria-label="Permalink to &quot;`session_cache_ttl` {#internal_tls.session_cache_ttl}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>0</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>internalTLS.sessionCacheTtl</code></dd></dl></div><p>Time a cached session may be resumed. <code>0</code> keeps it until the cache evicts it.</p><p>A negative value is refused at startup for every key above.</p>',120)])])}const _=t(r,[["render",d]]);export{u as __pageData,_ as default};
